#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_UPLOAD_SIZE 4096
#define WS_PORT 8080
#define ALLOWED_ORIGIN "app.internal.corp"

typedef struct {
    int fd;
    char origin[256];
    char resolved_ip[INET_ADDRSTRLEN];
    int validated;
} ws_conn_t;

typedef struct {
    char filename[128];
    char data[MAX_UPLOAD_SIZE];
    size_t len;
} upload_t;

static int resolve_and_check_origin(const char *hostname, char *ip_out) {
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, NULL, &hints, &res) != 0)
        return -1;

    struct sockaddr_in *addr = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &addr->sin_addr, ip_out, INET_ADDRSTRLEN);
    freeaddrinfo(res);

    /* Check that origin resolves to internal network */
    unsigned long ip_num = ntohl(addr->sin_addr.s_addr);
    if ((ip_num & 0xFF000000) == 0x0A000000 ||   /* 10.0.0.0/8 */
        (ip_num & 0xFFF00000) == 0xAC100000 ||   /* 172.16.0.0/12 */
        (ip_num & 0xFFFF0000) == 0xC0A80000) {   /* 192.168.0.0/16 */
        return 0; /* internal - allowed */
    }
    return -1;
}

static int validate_ws_origin(ws_conn_t *conn) {
    char ip_buf[INET_ADDRSTRLEN];

    /* Phase 1: Check hostname matches allowed origin */
    if (strncmp(conn->origin, ALLOWED_ORIGIN, strlen(ALLOWED_ORIGIN)) != 0)
        return -1;

    /* Phase 2: Resolve and verify it points to internal IP */
    if (resolve_and_check_origin(conn->origin, ip_buf) != 0)
        return -1;

    strncpy(conn->resolved_ip, ip_buf, INET_ADDRSTRLEN);
    conn->validated = 1;
    return 0;
}

static int process_upload(ws_conn_t *conn, const char *frame_data, size_t frame_len) {
    upload_t upload;
    memset(&upload, 0, sizeof(upload));

    /* Re-resolve origin to confirm it still points to internal network.
     * This prevents DNS rebinding by checking at time-of-use. */
    char current_ip[INET_ADDRSTRLEN];
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(conn->origin, NULL, &hints, &res) != 0)
        return -1;

    struct sockaddr_in *addr = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &addr->sin_addr, current_ip, INET_ADDRSTRLEN);
    freeaddrinfo(res);

    /* Verify the re-resolved IP matches what we validated at connection time */
    if (strcmp(current_ip, conn->resolved_ip) != 0) {
        fprintf(stderr, "DNS rebinding detected: %s -> %s (was %s)\n",
                conn->origin, current_ip, conn->resolved_ip);
        return -1;
    }

    /* Parse upload frame: first 128 bytes = filename, rest = data */
    if (frame_len < 129) return -1;
    memcpy(upload.filename, frame_data, 128);
    upload.filename[127] = '\0';
    upload.len = frame_len - 128;
    if (upload.len > MAX_UPLOAD_SIZE) upload.len = MAX_UPLOAD_SIZE;
    memcpy(upload.data, frame_data + 128, upload.len);

    /* Write to internal storage */
    char path[384];
    snprintf(path, sizeof(path), "/var/uploads/%s", upload.filename);
    FILE *f = fopen(path, "wb");
    if (!f) return -1;
    fwrite(upload.data, 1, upload.len, f);
    fclose(f);
    return 0;
}

static void *handle_connection(void *arg) {
    ws_conn_t *conn = (ws_conn_t *)arg;
    char buf[MAX_UPLOAD_SIZE + 256];

    if (validate_ws_origin(conn) != 0) {
        fprintf(stderr, "Origin validation failed for: %s\n", conn->origin);
        close(conn->fd);
        free(conn);
        return NULL;
    }

    /* WebSocket message loop */
    while (1) {
        ssize_t n = recv(conn->fd, buf, sizeof(buf), 0);
        if (n <= 0) break;
        process_upload(conn, buf, (size_t)n);
    }

    close(conn->fd);
    free(conn);
    return NULL;
}

int main(void) {
    int srv = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(WS_PORT);
    addr.sin_addr.s_addr = INADDR_ANY;

    bind(srv, (struct sockaddr *)&addr, sizeof(addr));
    listen(srv, 16);

    while (1) {
        struct sockaddr_in client;
        socklen_t clen = sizeof(client);
        int cfd = accept(srv, (struct sockaddr *)&client, &clen);
        if (cfd < 0) continue;

        ws_conn_t *conn = calloc(1, sizeof(ws_conn_t));
        conn->fd = cfd;
        /* In real code, origin is parsed from HTTP Upgrade headers */
        recv(cfd, conn->origin, sizeof(conn->origin) - 1, 0);

        pthread_t t;
        pthread_create(&t, NULL, handle_connection, conn);
        pthread_detach(t);
    }
    return 0;
}
